#include <algorithm>
#include <fstream>
#include <functional>
#include <limits>
#include <queue>
#include <utility>
#include <vector>
int main() {
    std::ifstream in("dining.in");std::ofstream out("dining.out");int n,m,k;in >> n >> m >> k;
    std::vector<std::vector<std::pair<int,int>>> graph(n);
    for(int i=0;i<m;++i){int u,v,w;in >> u >> v >> w;--u;--v;graph[u].push_back({v,w});graph[v].push_back({u,w});}
    std::vector<std::pair<int,long long>> food(k);for(auto& p:food){in >> p.first >> p.second;--p.first;}
    constexpr long long inf=std::numeric_limits<long long>::max()/4;
    auto shortest=[&](std::vector<long long> distance){
        using Entry=std::pair<long long,int>;std::priority_queue<Entry,std::vector<Entry>,std::greater<Entry>> heap;
        for(int u=0;u<n;++u) if(distance[u]<inf) heap.push({distance[u],u});
        while(!heap.empty()){auto [cost,u]=heap.top();heap.pop();if(cost!=distance[u]) continue;for(auto [v,w]:graph[u]) if(cost+w<distance[v]){distance[v]=cost+w;heap.push({distance[v],v});}}
        return distance;
    };
    std::vector<long long> initial(n,inf);initial[n-1]=0;auto base=shortest(initial);std::fill(initial.begin(),initial.end(),inf);
    for(auto [u,yum]:food) initial[u]=std::min(initial[u],base[u]-yum);
    auto adjusted=shortest(initial);for(int u=0;u<n-1;++u) out << (adjusted[u]<=base[u]?1:0) << '\n';
}
