    std::sort(subsets.begin(),subsets.end());long long compatible=0;
    for(std::size_t begin=0;begin<subsets.size();){std::size_t end=begin+1;while(end<subsets.size() && subsets[end]==subsets[begin]) ++end;long long amount=static_cast<long long>(end-begin);int length=0;for(int value:subsets[begin]) if(value!=0) ++length;long long pairs=amount*(amount-1)/2;compatible+=(length%2?pairs:-pairs);begin=end;}
    out << static_cast<long long>(n)*(n-1)/2-compatible << '\n';
